<template><v-container fluid class="pa-4"><v-toolbar density="comfortable" rounded="lg" class="mb-4"><template v-if="!selectedItem"><v-toolbar-title>DatesDev</v-toolbar-title></template><template v-else><v-btn variant="text" prepend-icon="mdi-arrow-left" @click="selectedItem=null">Назад</v-btn><v-toolbar-title>{{ itemLabel(selectedItem) }}</v-toolbar-title><v-btn color="primary" :loading="saving" @click="save">Сохранить</v-btn></template></v-toolbar><v-card v-if="!selectedItem" class="pa-4"><v-expansion-panels><v-expansion-panel v-for="month in grouped" :key="month.month"><v-expansion-panel-title>{{ month.month }}</v-expansion-panel-title><v-expansion-panel-text><v-list density="compact"><v-list-item v-for="it in month.items" :key="it.id" :title="itemLabel(it)" @click="open(it)"/></v-list></v-expansion-panel-text></v-expansion-panel></v-expansion-panels></v-card><v-card v-else class="pa-4"><v-row><v-col cols="3"><v-text-field v-model="draft.date" label="date"/></v-col><v-col cols="9"><v-text-field v-model="draft.title" label="title"/></v-col><v-col cols="6"><v-text-field v-model="draft.rank" label="rank"/></v-col><v-col cols="6"><v-text-field v-model="draft.place" label="place"/></v-col></v-row><v-row><v-col cols="3"><v-select v-model="selectedCompareYear" :items="years" label="Год"/></v-col></v-row><v-row v-for="field in FIELDS" :key="field"><v-col cols="6"><v-textarea v-model="draft[field]" :label="field" auto-grow rows="2"/></v-col><v-col cols="6"><v-textarea :model-value="compare[field]||''" :label="`${field} (${selectedCompareYear})`" auto-grow rows="2" readonly/></v-col></v-row></v-card></v-container></template>
<script setup>
import { computed, ref, watch } from 'vue';
import { collection, doc, getDocs, query, setDoc, where } from 'firebase/firestore';
import { db } from '@/plugins/firebase';
import { fixedCalendar } from '@/constants/fixedCalendar';
const years=[2025,2024,2023,2022,2021,2020,2019];
const rankMap={'урачыстасць':'solemnity','свята':'feast','успамін':'memorial'};
const placeMap={'гродзенская дыяцэзія':'grodno','віцебская дыяцэзія':'vitebsk','пінская дыяцэзія':'pinsk','мінска-магілёўская архідыяцэзія':'minsk-mogilev'};
const FIELDS=['_date','_feastName','_feastType','_feast','feastComment','invitatoriumAnt','officeOfReadingsHymn','officeOfReadingsAnt1','officeOfReadingsAnt2','officeOfReadingsAnt3','officeOfReadingsPs1','officeOfReadingsPs2','officeOfReadingsPs3','officeOfReadingsVers','officeOfReadingsR1','officeOfReadingsR2','officeOfReadingsTeDeum','officeOfReadingsPr','laudesHymn','laudesAnt1','laudesAnt2','laudesAnt3','laudesPs1','laudesPs2','laudesPs3','laudesR','laudesAntBen','laudesInter','laudesPr','sext1Hymn','sext1Ant1','sext1Ant2','sext1Ant3','sext1Ps1','sext1Ps2','sext1Ps3','sext1R','sext1Pr','sext2Hymn','sext2Ant1','sext2Ant2','sext2Ant3','sext2Ps1','sext2Ps2','sext2Ps3','sext2R','sext2Pr','sext3Hymn','sext3Ant1','sext3Ant2','sext3Ant3','sext3Ps1','sext3Ps2','sext3Ps3','sext3R','sext3Pr','vesperHymn','vesperAnt1','vesperAnt2','vesperAnt3','vesperPs1','vesperPs2','vesperPs3','vesperR','vesperAntMag','vesperInter','vesperPr','vesper1Hymn','vesper1Ant1','vesper1Ant2','vesper1Ant3','vesper1Ps1','vesper1Ps2','vesper1Ps3','vesper1R','vesper1AntMag','vesper1Inter','vesper1Pr'];
const selectedCompareYear=ref(2024), selectedItem=ref(null), draft=ref({}), compare=ref({}), saving=ref(false), fixedMap=ref(new Map());
const grouped=computed(()=>{const m=new Map(); fixedCalendar.forEach((x)=>{const id=idFor(x);const merged={...x,...(fixedMap.value.get(id)||{}),id}; const k=x.date.slice(3,5); if(!m.has(k))m.set(k,[]); m.get(k).push(merged)}); return [...m.entries()].map(([month,items])=>({month,items}));});
const norm=(v)=>String(v||'').trim().toLowerCase();
function idFor(x){const r=rankMap[norm(x.rank)]||norm(x.rank)||'none'; const p=placeMap[norm(x.place)]||norm(x.place)||'none'; return `${x.date}-${r}-${p}`.toLowerCase();}
function itemLabel(x){return `${x.date} — ${x.title}${x.rank?` (${x.rank})`:''}${x.place?` [${x.place}]`:''}`}
async function load(){const s=await getDocs(collection(db,'fixedDays')); fixedMap.value=new Map(s.docs.map((d)=>[d.id,d.data()]));}
async function open(x){selectedItem.value=x; draft.value={...x,...(fixedMap.value.get(x.id)||{})}; await loadCompare();}
async function loadCompare(){if(!selectedItem.value)return; const d=selectedItem.value.date; const ds=`${selectedCompareYear.value}-${d.slice(3,5)}-${d.slice(0,2)}`; const q=query(collection(db,'daysTmp'),where('_date','>=',ds),where('_date','<=',`${ds}T23:59:59`)); const s=await getDocs(q); compare.value=s.docs[0]?.data()||{};}
watch(selectedCompareYear,loadCompare);
async function save(){saving.value=true;const id=idFor(draft.value); await setDoc(doc(db,'fixedDays',id),{...draft.value,date:draft.value.date,title:draft.value.title,rank:draft.value.rank||'',place:draft.value.place||''},{merge:true}); saving.value=false; await load();}
load();
</script>
